<?php
namespace App\Http\Controllers;use App\Http\Resources\FleetDeviceResource;use App\Services\FleetService;use Illuminate\Http\Request;use Illuminate\Validation\Rule;
class FleetController extends Controller { public function index(Request $request,FleetService $service){abort_unless($request->user()->organization&&$request->user()->hasOrganizationPermission('device.view'),403);$filters=$request->validate(['search'=>['nullable','string','max:255'],'status'=>['nullable',Rule::in(['online','offline','maintenance','inactive'])],'device_template_id'=>['nullable','integer'],'access_level'=>['nullable',Rule::in(['viewer','full_access'])],'device_type'=>['nullable','string','max:100'],'protocol'=>['nullable','string','max:50'],'location_id'=>['nullable','integer','exists:locations,id'],'unassigned'=>['nullable','boolean'],'sort'=>['nullable',Rule::in(['name','identifier','status','last_seen','created_at'])],'direction'=>['nullable',Rule::in(['asc','desc'])],'per_page'=>['nullable','integer',Rule::in([25,50,100])],'page'=>['nullable','integer','min:1']]);if(isset($filters['location_id'])&&!\App\Models\Location::whereKey($filters['location_id'])->where('organization_id',$request->user()->organization_id)->exists())abort(404);$result=$service->result($request->user(),$filters);return FleetDeviceResource::collection($result['page'])->additional(['summary'=>$result['summary'],'filterOptions'=>['templates'=>$result['templates']]]);}}
